pub fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 as per the problem statement.
    let mut result = Vec::with_capacity(n);
    result.push(0);
    result.push(1);

    for i in 2..n {
        // Since the Fibonacci number at index n-1 is guaranteed < 2^31,
        // this addition cannot overflow an i32.
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }

    result
}

